#include <iostream>

// Classic C pass-by-value
int cubeByValue(int n) {
    return n * n * n;
}

// Classic C pass-by-reference using a pointer
void cubeByReference(int* nPtr) {
    if (nPtr != nullptr) {
        *nPtr = (*nPtr) * (*nPtr) * (*nPtr);
    }
}

// Modern C++17 pass-by-reference using an lvalue reference
void cubeCppReference(int& n) {
    n = n * n * n;
}

int main() {
    int num1 = 5;
    std::cout << "Initial num1: " << num1 << "\n";
    num1 = cubeByValue(num1);
    std::cout << "After cubeByValue: " << num1 << "\n";

    int num2 = 5;
    std::cout << "Initial num2: " << num2 << "\n";
    cubeByReference(&num2);
    std::cout << "After cubeByReference: " << num2 << "\n";

    int num3 = 5;
    std::cout << "Initial num3: " << num3 << "\n";
    cubeCppReference(num3);
    std::cout << "After cubeCppReference: " << num3 << "\n";

    return 0;
}

#include <iostream>
#include <cctype>

// 7.5.1: Non-constant pointer to non-constant data
// Modifies characters in-place and advances the pointer
void convertToUppercase(char* sPtr) {
    while (sPtr != nullptr && *sPtr != '\0') {
        *sPtr = static_cast<char>(std::toupper(static_cast<unsigned char>(*sPtr)));
        ++sPtr;
    }
}

// 7.5.2: Non-constant pointer to constant data
// Pointer advances, but the underlying characters are read-only
void printCharacters(const char* sPtr) {
    for (; sPtr != nullptr && *sPtr != '\0'; ++sPtr) {
        std::cout << *sPtr;
    }
}

int main() {
    char str[] = "cHaRaCters and $32.98";

    std::cout << "The string before conversion is: ";
    printCharacters(str);
    std::cout << "\n";

    convertToUppercase(str);

    std::cout << "The string after conversion is: ";
    printCharacters(str);
    std::cout << "\n";

    return 0;
}
